 pub fn take_demand(&self)->RetirementDemand{if self.documenting{return self.document.take_demand()}if self.overriding{return self.overrides.take_demand()}if self.data_fields{return self.data.take_demand()}if self.framing{return self.frame.take_demand()}if self.layering{return self.layer.take_demand()}if self.deleting{return self.deletion.take_demand()}RetirementDemand{copy_bytes:size_of::<Option<Vec<LayoutMutation>>>()*2,depth:1,..Default::default()}}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<(Option<Vec<LayoutMutation>>,RetainedCloneProgress),ValueError>{if self.documenting{return self.document.take(g)}if self.overriding{return self.overrides.take(g)}if self.data_fields{return self.data.take(g)}if self.framing{return self.frame.take(g)}if self.layering{return self.layer.take(g)}if self.deleting{return self.deletion.take(g)}if self.phase!=6||self.closing{return Err(fault())}let d=self.take_demand();if !retained_clone_grant_admits(g,d){return Ok((None,Default::default()))}self.phase=7;Ok((self.rows.take(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
